Definition kernel_bytes : gmap Z (bv 8) :=
  list_to_map (List.concat [
    kernel_bytes_chunk0; kernel_bytes_chunk1; kernel_bytes_chunk2; kernel_bytes_chunk3;
    kernel_bytes_chunk4; kernel_bytes_chunk5; kernel_bytes_chunk6; kernel_bytes_chunk7;
    kernel_bytes_chunk8; kernel_bytes_chunk9; kernel_bytes_chunk10; kernel_bytes_chunk11;
    kernel_bytes_chunk12; kernel_bytes_chunk13; kernel_bytes_chunk14; kernel_bytes_chunk15;
    kernel_bytes_chunk16; kernel_bytes_chunk17; kernel_bytes_chunk18; kernel_bytes_chunk19;
    kernel_bytes_chunk20; kernel_bytes_chunk21; kernel_bytes_chunk22; kernel_bytes_chunk23
  ]).

(* Total bytes = 23992 (from 8700 instructions); keys are byte
   addresses, so [kernel_bytes !! addr] yields that byte. *)

Global Typeclasses Opaque kernel_bytes.

(* KEY RANGE.  [kernel_bytes_lo <= a < kernel_bytes_hi] for every key [a]: the decidable
   [map_Forall] check, closed by one [vm_compute], so the proof term is
   [eq_refl] and no list ever enters it.  Bounds are LITERALS (this file
   is below iris/ and cannot name [ram_lo]/[text_end]/[img_end]); the
   consumer bridges them arithmetically. *)
Definition kernel_bytes_lo : Z := 0x80000000%Z.
Definition kernel_bytes_hi : Z := 0x80006124%Z.

Lemma kernel_bytes_range_bool :
  bool_decide (map_Forall (fun (a : Z) (_ : bv 8) =>
                 (kernel_bytes_lo <= a < kernel_bytes_hi)%Z) kernel_bytes) = true.
Proof. vm_compute. reflexivity. Qed.

Lemma kernel_bytes_range (a : Z) (b : bv 8) :
  kernel_bytes !! a = Some b -> (kernel_bytes_lo <= a < kernel_bytes_hi)%Z.
Proof.
  pose proof kernel_bytes_range_bool as H.
  apply bool_decide_eq_true_1 in H. exact (H a b).
Qed.

